def solution():
    total_assets = 12531 # Total Assets value on March 31, 2014
    current_liabilities = 773 # Total Current Liabilities on March 31, 2014

    no_shares_outstanding = 58524052 # number of common shares outstanding on March 31, 2014
    money_per_share = (total_assets - current_liabilities) / no_shares_outstanding
    return round(money_per_share, 3)
